import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_kernel_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <math.h>

#define BLOCK_SIZE 256
#define MAX_GROUPS 32

__device__ float warpMin(float val) {
    for (int offset = 16; offset > 0; offset /= 2) 
        val = fminf(val, __shfl_down_sync(0xffffffff, val, offset));
    return val;
}

__global__ void fused_groupnorm_min_bias_kernel(
    const float* input,
    const float* bias,
    float* output,
    int N, int C, int G,
    float eps) {

    extern __shared__ float smem[];
    float* shared = smem;

    int n = blockIdx.x;
    int tid = threadIdx.x;
    int lane = tid % 32;
    int warp = tid / 32;

    // Load input into shared memory
    if (tid < C) shared[tid] = input[n * C + tid];
    __syncthreads();

    // GroupNorm calculations per warp
    if (warp < G) {
        int group_size = C / G;
        int group_start = warp * group_size;
        int idx = group_start + lane;

        float x = (lane < group_size) ? shared[idx] : 0.0f;

        // Warp reduction for sum and sum_sq
        float sum = x;
        float sum_sq = x * x;
        for (int offset = 16; offset > 0; offset /= 2) {
            sum += __shfl_down_sync(0xffffffff, sum, offset);
            sum_sq += __shfl_down_sync(0xffffffff, sum_sq, offset);
        }

        if (lane == 0) {
            float mean = sum / group_size;
            float var = (sum_sq / group_size) - (mean * mean);
            shared[C + warp] = mean;
            shared[C + G + warp] = var;
        }
    }
    __syncthreads();

    // Normalize data
    if (warp < G) {
        int group_size = C / G;
        int group_start = warp * group_size;
        int idx = group_start + lane;

        if (idx < C) {
            float mean = shared[C + warp];
            float var = shared[C + G + warp];
            float std = sqrtf(var + eps);
            shared[idx] = (shared[idx] - mean) / std;
        }
    }
    __syncthreads();

    // Block-wide min reduction
    float val = (tid < C) ? shared[tid] : INFINITY;
    float block_min = warpMin(val);
    if (lane == 0) shared[warp] = block_min;
    __syncthreads();

    if (tid < 32) {
        val = (tid < G) ? shared[tid] : INFINITY;
        block_min = warpMin(val);
    }
    __syncthreads();

    // Add bias and write output
    if (tid < C) {
        float min_val = block_min;
        output[n * C + tid] = min_val + bias[tid];
    }
}

torch::Tensor fused_op_cuda(
    torch::Tensor input,
    torch::Tensor bias,
    int G,
    float eps) {

    auto N = input.size(0);
    auto C = input.size(1);

    auto output = torch::empty({N, C, 1, 1}, input.options());

    dim3 grid(N);
    dim3 block(BLOCK_SIZE);
    size_t smem = (C + 2*MAX_GROUPS) * sizeof(float);

    fused_groupnorm_min_bias_kernel<<<grid, block, smem>>>(
        input.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        N, C, G, eps);

    return output;
}
"""

fused_kernel_cpp = """
torch::Tensor fused_op_cuda(torch::Tensor input, torch::Tensor bias, int G, float eps);
"""

fused_op = load_inline(
    name='fused_op',
    cpp_sources=fused_kernel_cpp,
    cuda_sources=fused_kernel_source,
    functions=['fused_op_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_features, out_features, num_groups, bias_shape):
        super().__init__()
        self.gemm = nn.Linear(in_features, out_features)
        self.bias = nn.Parameter(torch.randn(bias_shape))
        self.num_groups = num_groups
        self.eps = 1e-5

        # Ensure bias is contiguous and properly shaped
        self.register_buffer('bias_flat', self.bias.view(-1))

    def forward(self, x):
        x = self.gemm(x)  # [N, C]
        x = fused_op.fused_op_cuda(x, self.bias_flat, self.num_groups, self.eps)
        return x
